package com.allthinkstars.framework.iot.app.tools;

import com.allthinkstars.framework.iot.ai.config.AiProperties;
import com.allthinkstars.framework.iot.ai.tools.ToolArgsInvalidException;
import com.allthinkstars.framework.iot.ai.tools.ToolExecException;
import com.allthinkstars.framework.iot.ai.tools.erp.AiErpOutsourceOrderForm;
import com.allthinkstars.framework.iot.ai.tools.erp.AiErpPurchaseDocumentForm;
import com.allthinkstars.framework.iot.ai.tools.erp.AiErpSearchRequest;
import com.allthinkstars.framework.iot.ai.tools.erp.AiErpStockDocumentForm;
import com.allthinkstars.framework.iot.ai.tools.erp.AiErpToolResult;
import com.allthinkstars.framework.iot.ai.tools.inventory.AiInventoryQuery;
import com.allthinkstars.framework.iot.ai.tools.inventory.AiInventoryResult;
import com.allthinkstars.framework.iot.ai.tools.support.AiRunContext;
import com.allthinkstars.framework.iot.ai.tools.support.annotation.AiToolComponent;
import com.allthinkstars.framework.iot.ai.tools.support.annotation.AiToolDef;
import com.allthinkstars.framework.iot.ai.tools.support.annotation.AiToolParam;
import com.allthinkstars.framework.iot.app.client.AiErpInternalClient;
import feign.FeignException;
import lombok.RequiredArgsConstructor;
import org.apache.commons.lang3.StringUtils;

import java.util.Locale;
import java.util.List;
import java.util.function.Supplier;

/**
 * ERP 产品采购、入库和委外 MCP Tool。
 */
@AiToolComponent
@RequiredArgsConstructor
public class AiErpDocumentTools {

    private final AiErpInternalClient erpClient;
    private final AiProperties aiProperties;

    @AiToolDef(
        name = "search_erp_product_inventory",
        value = "分页查询 ERP 物料/产品 SKU 库存。productSkuIds 为空时查全部；物料、编码和仓库条件同时传入时按 AND 过滤。不得传炉料ID。",
        outputDescription = "ERP 产品 SKU 库存合计和仓库库存明细",
        progressText = "正在查询 ERP 产品库存",
        successText = "已查询 ERP 产品库存"
    )
    public AiInventoryResult searchInventory(
        @AiToolParam(name = "productSkuIds", value = "jsh_material_extend ID 列表；可为空，最多200个", title = "产品SKU ID列表") List<Long> productSkuIds,
        @AiToolParam(name = "warehouseName", value = "仓库名称模糊过滤", title = "仓库名称") String warehouseName,
        @AiToolParam(name = "materialName", value = "物料或产品名称模糊过滤", title = "物料名称") String materialName,
        @AiToolParam(name = "materialCode", value = "业务编码或条码模糊过滤", title = "物料编码") String materialCode,
        @AiToolParam(name = "page", value = "页码，默认1", title = "页码") Integer page,
        @AiToolParam(name = "pageSize", value = "每页数量，默认50，最大200", title = "每页数量") Integer pageSize,
        AiRunContext ctx
    ) {
        AiInventoryQuery query = inventoryQuery(productSkuIds, warehouseName, materialName, materialCode,
            null, null, page, pageSize);
        return invoke(() -> erpClient.searchInventory(token(), tenant(ctx), user(ctx), query));
    }

    @AiToolDef(
        name = "search_erp_product_inventory_changes",
        value = "分页查询一个 ERP 产品 SKU 的近期库存变化。不传日期时按时间倒序返回，默认最近20条。不得传炉料ID。",
        outputDescription = "ERP 产品 SKU 的出入库、调拨、组装、拆卸和盘点记录",
        progressText = "正在查询 ERP 产品库存变更",
        successText = "已查询 ERP 产品库存变更"
    )
    public AiInventoryResult searchInventoryChanges(
        @AiToolParam(name = "productSkuId", value = "jsh_material_extend ID", title = "产品SKU ID", required = true) Long productSkuId,
        @AiToolParam(name = "warehouseName", value = "仓库名称模糊过滤", title = "仓库名称") String warehouseName,
        @AiToolParam(name = "startDate", value = "开始日期 yyyy-MM-dd，包含当天", title = "开始日期") String startDate,
        @AiToolParam(name = "endDate", value = "结束日期 yyyy-MM-dd，包含当天", title = "结束日期") String endDate,
        @AiToolParam(name = "page", value = "页码，默认1", title = "页码") Integer page,
        @AiToolParam(name = "pageSize", value = "每页数量，默认20，最大100", title = "每页数量") Integer pageSize,
        AiRunContext ctx
    ) {
        AiInventoryQuery query = inventoryQuery(null, warehouseName, null, null, startDate, endDate, page, pageSize);
        return invoke(() -> erpClient.searchInventoryChanges(
            token(), tenant(ctx), user(ctx), productSkuId, query));
    }

    @AiToolDef(
        name = "search_erp_product",
        value = "查询 jsh_material/jsh_material_extend ERP 产品或物料。创建采购、入库、委外单据前必须从结果选择 productSkuId；不得传炉料ID。",
        outputDescription = "ERP 产品/SKU 候选",
        progressText = "正在查询 ERP 产品",
        successText = "已查询 ERP 产品"
    )
    public AiErpToolResult searchProduct(
        @AiToolParam(name = "keyword", value = "产品名称、业务编码、规格或型号关键字", title = "产品关键字") String keyword,
        @AiToolParam(name = "limit", value = "默认10，最大50", title = "返回条数", examples = {"10"}) Integer limit,
        AiRunContext ctx
    ) {
        return invoke(() -> erpClient.searchProducts(token(), tenant(ctx), user(ctx), search(keyword, null, limit)));
    }

    @AiToolDef(
        name = "search_erp_supplier",
        value = "查询当前工厂启用的 ERP 供应商。采购或委外创建前必须从结果选择 supplierId。",
        outputDescription = "ERP 供应商候选",
        progressText = "正在查询当前工厂供应商",
        successText = "已查询当前工厂供应商"
    )
    public AiErpToolResult searchSupplier(
        @AiToolParam(name = "keyword", value = "供应商名称关键字", title = "供应商关键字") String keyword,
        @AiToolParam(name = "limit", value = "默认10，最大50", title = "返回条数", examples = {"10"}) Integer limit,
        AiRunContext ctx
    ) {
        return invoke(() -> erpClient.searchSuppliers(token(), tenant(ctx), user(ctx), search(keyword, null, limit)));
    }

    @AiToolDef(
        name = "search_erp_depot",
        value = "查询当前工厂启用的 ERP 产品仓库。创建产品入库单前必须从结果选择 depotId。",
        outputDescription = "ERP 产品仓库候选",
        progressText = "正在查询当前工厂产品仓库",
        successText = "已查询当前工厂产品仓库"
    )
    public AiErpToolResult searchDepot(
        @AiToolParam(name = "keyword", value = "仓库名称关键字", title = "仓库关键字") String keyword,
        @AiToolParam(name = "limit", value = "默认10，最大50", title = "返回条数", examples = {"10"}) Integer limit,
        AiRunContext ctx
    ) {
        return invoke(() -> erpClient.searchDepots(token(), tenant(ctx), user(ctx), search(keyword, null, limit)));
    }

    @AiToolDef(
        name = "search_erp_purchase",
        value = "按单号查询当前工厂的请购单、采购订单或采购入库单。业务类型始终以 ERP type/subType 为准，不按单号前缀推断。",
        outputDescription = "真实采购单据类型和关联信息",
        progressText = "正在查询采购单据",
        successText = "已查询采购单据"
    )
    public AiErpToolResult searchPurchase(
        @AiToolParam(name = "number", value = "完整采购单号", title = "采购单号", required = true) String number,
        AiRunContext ctx
    ) {
        return invoke(() -> erpClient.searchPurchases(token(), tenant(ctx), user(ctx), search(null, number, 10)));
    }

    @AiToolDef(
        name = "create_erp_purchase_document",
        value = "两阶段创建 ERP 请购单或采购订单。prepare 返回服务端补全的完整 form，不写业务表；用户确认后将完整 form 原样用于 confirm，confirm 会重新校验并同时关联原始PDF。",
        outputDescription = "采购单据预览或创建结果",
        progressText = "正在处理采购单据",
        successText = "已处理采购单据"
    )
    public AiErpToolResult createPurchase(
        @AiToolParam(name = "action", value = "prepare-预览，confirm-确认创建", title = "执行动作", required = true) String action,
        @AiToolParam(name = "form", value = "采购完整表单", title = "采购表单", required = true) AiErpPurchaseDocumentForm form,
        AiRunContext ctx
    ) {
        return invoke(() -> erpClient.executePurchase(token(), tenant(ctx), user(ctx), action(action), form));
    }

    @AiToolDef(
        name = "create_erp_product_stock_document",
        value = "两阶段创建 ERP 产品采购入库、委外入库或其他入库单。prepare 不写业务表；confirm 重新校验、复用 ERP 库存逻辑并同时关联原始PDF。",
        outputDescription = "ERP 产品入库单预览或创建结果",
        progressText = "正在处理产品入库单据",
        successText = "已处理产品入库单据"
    )
    public AiErpToolResult createStock(
        @AiToolParam(name = "action", value = "prepare-预览，confirm-确认创建", title = "执行动作", required = true) String action,
        @AiToolParam(name = "form", value = "产品入库完整表单", title = "入库表单", required = true) AiErpStockDocumentForm form,
        AiRunContext ctx
    ) {
        return invoke(() -> erpClient.executeStock(token(), tenant(ctx), user(ctx), action(action), form));
    }

    @AiToolDef(
        name = "create_erp_outsource_order",
        value = "两阶段创建 ERP 委外任务及所需物料。prepare 不写业务表；confirm 重新校验、复用委外服务并同时关联原始PDF。",
        outputDescription = "委外订单预览或创建结果",
        progressText = "正在处理委外订单",
        successText = "已处理委外订单"
    )
    public AiErpToolResult createOutsource(
        @AiToolParam(name = "action", value = "prepare-预览，confirm-确认创建", title = "执行动作", required = true) String action,
        @AiToolParam(name = "form", value = "委外订单完整表单", title = "委外表单", required = true) AiErpOutsourceOrderForm form,
        AiRunContext ctx
    ) {
        return invoke(() -> erpClient.executeOutsource(token(), tenant(ctx), user(ctx), action(action), form));
    }

    private AiErpSearchRequest search(String keyword, String number, Integer limit) {
        AiErpSearchRequest request = new AiErpSearchRequest();
        request.setKeyword(keyword);
        request.setNumber(number);
        request.setLimit(limit);
        return request;
    }

    private String action(String action) {
        String normalized = StringUtils.defaultString(action).trim().toLowerCase(Locale.ROOT);
        if (!"prepare".equals(normalized) && !"confirm".equals(normalized)) {
            throw new ToolArgsInvalidException("action仅支持 prepare 或 confirm");
        }
        return normalized;
    }

    private String token() {
        String token = aiProperties.getMcp() == null ? null : aiProperties.getMcp().getInternalToken();
        if (StringUtils.isBlank(token)) {
            throw new ToolExecException("erp_internal_token_missing", "AI ERP内部调用token未配置");
        }
        return token;
    }

    private Long tenant(AiRunContext ctx) {
        if (ctx == null || ctx.getTenantId() == null) {
            throw new ToolExecException("empty_scope", "当前工厂上下文缺失");
        }
        return ctx.getTenantId();
    }

    private Long user(AiRunContext ctx) {
        if (ctx == null || ctx.getSysUserId() == null) {
            throw new ToolExecException("empty_user", "当前用户上下文缺失");
        }
        return ctx.getSysUserId();
    }

    private <T> T invoke(Supplier<T> operation) {
        try {
            return operation.get();
        } catch (FeignException e) {
            String message = StringUtils.defaultIfBlank(e.contentUTF8(), e.getMessage());
            throw new ToolExecException("erp_internal_call_failed", message);
        }
    }

    private AiInventoryQuery inventoryQuery(List<Long> ids, String warehouseName, String materialName,
                                            String materialCode, String startDate, String endDate,
                                            Integer page, Integer pageSize) {
        AiInventoryQuery query = new AiInventoryQuery();
        query.setIds(ids);
        query.setWarehouseName(warehouseName);
        query.setMaterialName(materialName);
        query.setMaterialCode(materialCode);
        query.setStartDate(startDate);
        query.setEndDate(endDate);
        query.setPage(page);
        query.setPageSize(pageSize);
        return query;
    }
