from __future__ import annotations

from src.assertions import run_assertions
from src.client import extract_tool_names
from src.scenario import Expects


def _final(content: str) -> dict:
    return {"message_type": "final", "content": content}


def _tool_call() -> dict:
    return {"message_type": "tool_call", "data": {"tool_call_id": "t1"}}


def _tool_result(is_error: bool = False) -> dict:
    return {"message_type": "tool_result", "data": {"tool_call_id": "t1", "is_error": is_error}}


def _raw_entry_with_tool(tool_name: str) -> dict:
    """模拟内部 store 返回的 raw Pi SessionEntry（assistant 消息含 toolCall block）。"""
    return {
        "type": "message",
        "message": {"role": "assistant", "content": [{"type": "toolCall", "name": tool_name, "id": "x"}]},
    }


def test_pass_when_final_and_tool_called():
    messages = [_tool_call(), _tool_result(), _final("今天3号炉有5个炉次，状态进行中")]
    result = run_assertions(messages, Expects(terminal="final", min_tools=1))
    assert result.passed is True
    assert result.failures == []


def test_fail_when_min_tools_not_met():
