    messages = [_tool_call(), _final("今天3号炉的生产计划是5个炉次，都在进行中")]
    result = run_assertions(
        messages,
        Expects(terminal="final", min_tools=1, no_leak=["planId", "statusName", "fnCode"]),
    )
