    private Long requireTenant(AiRunContext ctx) {
        if (ctx == null || ctx.getTenantId() == null) {
            throw new ToolExecException("empty_scope", "当前工厂上下文缺失，无法操作物料库存");
        }
        return ctx.getTenantId();
    }

    private AiMaterialStockDocumentResult invoke(Supplier<AiMaterialStockDocumentResult> operation) {
        try {
            return operation.get();
        } catch (ServiceException e) {
            // 业务服务同时供 Web 使用；MCP 入口在这里将表单校验失败映射为稳定的工具参数错误。
            throw new ToolArgsInvalidException(e.getMessage());
        }
    }

    private AiInventoryResult invokeInventory(Supplier<AiInventoryResult> operation) {
        try {
            return operation.get();
        } catch (ServiceException e) {
            throw new ToolArgsInvalidException(e.getMessage());
        }
    }

    private AiInventoryQuery inventoryQuery(List<Long> ids, String warehouseName, String materialName,
                                            String materialCode, String startDate, String endDate,
                                            Integer page, Integer pageSize) {
        AiInventoryQuery query = new AiInventoryQuery();
