public AiErpToolResult searchDepots(AiErpSearchRequest request) throws Exception {
    String keyword = StringUtils.trimToEmpty(request == null ? null : request.getKeyword());
    int limit = limit(request);

    AiErpToolResult result = result("found", "ERP仓库查询完成");
    for (Depot depot : safe(depotService.findUserDepot())) {
        if (result.getCandidates().size() >= limit) {
            break;
        }
        if (StringUtils.isNotBlank(keyword)
            && !StringUtils.containsIgnoreCase(depot.getName(), keyword)) {
            continue;
        }
        AiErpToolResult.Option option = new AiErpToolResult.Option();
        option.setId(depot.getId());
        option.setName(depot.getName());
        option.setType(depot.getType() == null ? null : String.valueOf(depot.getType()));
        option.setStatus(Boolean.TRUE.equals(depot.getEnabled()) ? "enabled" : "disabled");
        result.getCandidates().add(option);
    }
    return result;
}

public AiErpToolResult searchPurchases(AiErpSearchRequest request) throws Exception {
    String number = required(request == null ? null : request.getNumber(), "采购单号不能为空");
    DepotHead head = depotHeadService.getDepotHead(number);
    String kind = head == null ? null : depotKind(head);

    AiErpToolResult result = result(kind == null ? "not_found" : "found",
        kind == null ? "未找到支持的采购单据" : "采购单据查询完成");
    if (kind != null) {
        AiErpToolResult.Option option = new AiErpToolResult.Option();
        option.setId(head.getId());
        option.setCode(head.getNumber());
        option.setName(head.getSubType());
        option.setType(kind);
        option.setStatus(head.getStatus());
        option.setRelatedId(head.getOrganId());
        result.getCandidates().add(option);
    }
    return result;
}

