/**
 * 将人工填写的表单补齐为可确认的预览。金额和出库成本始终由服务端重新计算。
 */
public AiMaterialStockDocumentResult prepare(AiMaterialStockDocumentForm form, Long tenantId) {
    Long currentTenantId = requireTenant(tenantId);
    validateForm(form);
    form.setDirection(normalizeDirection(form.getDirection()));
    form.setDocumentDate(normalizeDate(form.getDocumentDate()));

    BigDecimal amountTotal = BigDecimal.ZERO;
    BigDecimal costTotal = BigDecimal.ZERO;
    for (AiMaterialStockDocumentForm.Line line : form.getLines()) {
        validateLine(line, currentTenantId, "IN".equals(form.getDirection()));
        if ("IN".equals(form.getDirection())) {
            // 入库价格可由历史平均价补齐，但最终金额仍按本次表单的单价、数量和税率计算。
            fillInboundPreview(line);
            amountTotal = amountTotal.add(line.getPreviewAmount());
        } else {
            // 出库必须以确认瞬间的库存成本重新预估，禁止信任前端回传的 previewCost。
            fillOutboundPreview(line);
            costTotal = costTotal.add(line.getPreviewCost());
        }
    }

    AiMaterialStockDocumentResult result = new AiMaterialStockDocumentResult();
    result.setState("preview_ready");
    result.setForm(form);
    result.setPreviewAmountTotal(amountTotal);
    result.setPreviewCostTotal(costTotal);
    return result;
}

/**
 * 确认时先走完整预览校验，再为全部明细分配同一个单据编号并原子落库。
 */
@Transactional(value = "transactionManager", rollbackFor = Exception.class)
public AiMaterialStockDocumentResult confirm(AiMaterialStockDocumentForm form, Long tenantId) {
    AiMaterialStockDocumentResult preview = prepare(form, tenantId);
    String documentNum = "IN".equals(form.getDirection())
        ? materialStockManageService.generateInDocNum()
        : materialStockManageService.generateOutDocNum();

    for (AiMaterialStockDocumentForm.Line line : form.getLines()) {
        if ("IN".equals(form.getDirection())) {
            materialStockManageService.addMaterialInRecord(toInboundParam(form, line, documentNum));
        } else {
            materialStockManageService.addMaterialOutRecord(toOutboundParam(form, line, documentNum));
        }
    }

    preview.setState("created");
    preview.setDocumentNum(documentNum);
    preview.setCreatedLineCount(form.getLines().size());
    return preview;
}

private void validateForm(AiMaterialStockDocumentForm form) {
    if (form == null) {
        throw new ServiceException("出入库表单不能为空");
    }
    normalizeDirection(form.getDirection());
    if (form.getLines() == null || form.getLines().isEmpty()) {
        throw new ServiceException("至少需要一条物料明细");
    }
}

private void validateLine(AiMaterialStockDocumentForm.Line line, Long tenantId, boolean inbound) {
    if (line == null || line.getMaterialId() == null || line.getDepotId() == null) {
        throw new ServiceException("物料明细必须包含物料和仓库");
    }
    if (line.getQuantity() == null || line.getQuantity().compareTo(BigDecimal.ZERO) <= 0) {
        throw new ServiceException("物料数量必须大于0");
    }
    resolveMaterial(line.getMaterialId(), tenantId);
    resolveDepot(line.getDepotId(), tenantId);
    if (inbound) {
        resolveSupplier(line, tenantId);
    }
}

private void fillInboundPreview(AiMaterialStockDocumentForm.Line line) {
    if (line.getUnitPrice() == null) {
        MaterialDepotAndSupplierAvgPriceVo averagePrice = materialStockManageService.materialDepotAndSupplierAvgPrice(line.getMaterialId());
        if (averagePrice == null || averagePrice.getUnitPriceAvgLastMonth() == null
            || averagePrice.getUnitPriceAvgLastMonth() <= 0D) {
            throw new ServiceException("未找到近一个月入库均价，请填写含税单价");
        }
        line.setUnitPrice(BigDecimal.valueOf(averagePrice.getUnitPriceAvgLastMonth()));
    }
    if (line.getUnitPrice().compareTo(BigDecimal.ZERO) < 0) {
        throw new ServiceException("含税单价不能小于0");
    }
    line.setTaxRate(line.getTaxRate() == null ? BigDecimal.ZERO : line.getTaxRate());

    InRecordCaculateResultParam calculateParam = new InRecordCaculateResultParam();
    calculateParam.setUnitPrice(line.getUnitPrice());
    calculateParam.setQuantity(line.getQuantity());
    calculateParam.setTaxRatePercent(line.getTaxRate());
    InRecordCaculateResultVo amount = InRecordCaculateResultVo.cal(calculateParam);
    line.setPreviewAmount(amount.getAmountWithTax());
    line.setPreviewCost(null);
}

private void fillOutboundPreview(AiMaterialStockDocumentForm.Line line) {
    String calculation = StringUtils.defaultIfBlank(line.getAmountCalculation(), BusinessConstants.OUT_COST_CACULATION.FIFO)
        .trim().toUpperCase(Locale.ROOT);
    if (!Arrays.asList(BusinessConstants.OUT_COST_CACULATION.FIFO, BusinessConstants.OUT_COST_CACULATION.LIFO,
        BusinessConstants.OUT_COST_CACULATION.MANUAL).contains(calculation)) {
        throw new ServiceException("出库成本计算方式仅支持 FIFO、LIFO 或 MANUAL");
    }
    line.setAmountCalculation(calculation);
    line.setPreviewCost(materialStockManageService.preCalOutAmount(
        line.getMaterialId(), line.getDepotId(), line.getQuantity(), calculation));
    line.setPreviewAmount(null);
}

