 */
@Data
public class ToolResult {
    private boolean ok;
    private String code;
    private String message;
    /**
     * 返回给 LLM/前端的短摘要（会在 SSE 中截断）
     * 约定：尽量把“可读的结论”放这里，把结构化结果放 payload
     */
    private String preview;
    private ToolPayload payload;

    public static ToolResult ok(String preview, ToolPayload payload) {
        ToolResult r = new ToolResult();
        r.ok = true;
        r.preview = preview == null ? "" : preview;
        r.payload = payload;
        return r;
    }

    public static ToolResult fail(String code, String message) {
        ToolResult r = new ToolResult();
        r.ok = false;
        r.code = code;
        r.message = message;
