--- config ---
"""运行配置加载：YAML + 环境变量覆盖。"""
from __future__ import annotations

from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

import yaml


@dataclass
class Config:
    """运行配置。默认值仅为本地占位，正式值从 config.yaml 读取。"""

    base_url: str = "http://127.0.0.1:10002/epservice/api/ai"
    login_url: str = ""
    store_base_url: str = ""  # Java 网关 base，用于内部 store raw entries（工具名断言）
    gateway_token: str = ""   # X-AI-GW-TOKEN，访问内部 store 用
    poll_seconds: int = 90
    output_dir: str = "./logs/cases"
    auth: dict[str, Any] = field(default_factory=dict)

    @property
    def api_root(self) -> str:
        """从 base_url 去掉 /api/ai 或 /ai 后缀得到 Java API 根。"""
        base = self.base_url.rstrip("/")
        if base.endswith("/api/ai"):
            return base[: -len("/api/ai")]
        if base.endswith("/ai"):
            return base[: -len("/ai")]
        return base

    @property
    def store_base(self) -> str:
        """内部 store 的 Java 网关 base，默认等于 api_root。"""
        return (self.store_base_url or self.api_root).rstrip("/")


def load_config(path: str | Path | None) -> Config:
    """读取 YAML 配置；文件缺失时使用默认值。"""
    cfg = Config()
    if path and Path(path).exists():
        raw = yaml.safe_load(Path(path).read_text(encoding="utf-8")) or {}
        env = raw.get("environment") or {}
        auth = raw.get("auth") or {}
        cfg.base_url = env.get("base_url", cfg.base_url)
        cfg.login_url = env.get("login_url", "")
        cfg.store_base_url = env.get("store_base_url", "")
        cfg.gateway_token = auth.get("gateway_token", "")
        cfg.poll_seconds = int(env.get("poll_seconds", cfg.poll_seconds))
        cfg.output_dir = env.get("output_dir", cfg.output_dir)
        cfg.auth = auth
    return cfg

