"""登录与身份上下文：固定测试账号登录拿 Bearer token，并解析真实 userId/deptId。"""
from __future__ import annotations

import json
from typing import Any

import httpx

from .config import Config


def _find_token(value: Any) -> str:
    """递归从登录响应里找 token 字段。"""
    if isinstance(value, dict):
        for key in ("token", "accessToken", "access_token", "jwt", "jwtToken"):
            candidate = value.get(key)
            if isinstance(candidate, str) and candidate.strip():
                return candidate.strip()
        for item in value.values():
            token = _find_token(item)
            if token:
                return token
    elif isinstance(value, list):
        for item in value:
            token = _find_token(item)
            if token:
                return token
    return ""


def login(cfg: Config, client: httpx.Client) -> str:
    """登录并返回 Bearer token。登录地址默认从 base_url 推导。"""
    login_url = cfg.login_url or f"{cfg.api_root}/unified/login"
    payload: dict[str, Any] = {
        cfg.auth.get("login_field_mobile", "mobileNo"): cfg.auth.get("mobile_no", ""),
        cfg.auth.get("login_field_password", "password"): cfg.auth.get("password", ""),
    }
    extra = cfg.auth.get("login_extra_json")
    if isinstance(extra, str) and extra.strip():
        try:
            payload.update(json.loads(extra))
        except json.JSONDecodeError as exc:
            raise ValueError(f"login_extra_json 非法：{exc}") from exc

    resp = client.post(login_url, json=payload)
    resp.raise_for_status()
    token = _find_token(resp.json())
    if not token:
        raise RuntimeError(f"登录失败，无法提取 token：{resp.text[:200]}")
    return token


def _unwrap(payload: Any) -> Any:
    """解包 Java R<T> / 常见 envelope 的 data 字段。"""
    if isinstance(payload, dict):
        for key in ("data", "result", "body"):
            value = payload.get(key)
            if value is not None:
                return value
    return payload


def resolve_identity(cfg: Config, client: httpx.Client, token: str) -> dict[str, str] | None:
    """登录后解析真实 userId / deptId，供内部 store 查询会话归属用。失败返回 None。"""
    url = f"{cfg.api_root}/user/getUserInfo"
    try:
        resp = client.get(url, headers={"Authorization": f"Bearer {token}"})
        resp.raise_for_status()
        user = _unwrap(resp.json())
    except (httpx.HTTPError, ValueError):
        return None
    if not isinstance(user, dict):
        return None

    user_id = user.get("userId") or user.get("id")
    dept_id = user.get("deptId")
    if not dept_id and isinstance(user.get("dept"), dict):
        dept_id = user["dept"].get("deptId") or user["dept"].get("id")
    if user_id in (None, "") or dept_id in (None, ""):
        return None
    return {"userId": str(user_id), "deptId": str(dept_id)}

