				if (next.done) break;
				if (response.destroyed) break;
				response.write(next.value);
			}
		} finally {
			if (response.destroyed) await reader.cancel();
			reader.releaseLock();
		}
		if (!response.destroyed) response.end();
	} finally {
		if (eventStream) response.off("close", abortUpstream);
	}
}

