"""确定性断言：基于 pi runtime 的 messages 结构 + 内部 store 工具名。"""
from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Any

from .scenario import Expects


@dataclass
class AssertionResult:
    """断言结果：passed 为总判定，checks/failures 记录逐项证据。"""

    passed: bool = True
    checks: list[str] = field(default_factory=list)
    failures: list[str] = field(default_factory=list)


def _message_types(messages: list[dict[str, Any]]) -> list[str]:
    return [str(m.get("message_type") or "") for m in messages if isinstance(m, dict)]


def _final_texts(messages: list[dict[str, Any]]) -> list[str]:
    """收集 final（assistant 回答）消息的正文文本。"""
    texts: list[str] = []
    for m in messages:
        if not isinstance(m, dict) or m.get("message_type") != "final":
            continue
        content = m.get("content")
        if isinstance(content, str) and content.strip():
            texts.append(content)
        data = m.get("data")
        if isinstance(data, dict):
            for key in ("content", "answer"):
                value = data.get(key)
                if isinstance(value, str) and value.strip():
                    texts.append(value)
    return texts


def _tool_calls(messages: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return [m for m in messages if isinstance(m, dict) and m.get("message_type") == "tool_call"]


def _tool_results(messages: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return [m for m in messages if isinstance(m, dict) and m.get("message_type") == "tool_result"]


def _result_is_error(message: dict[str, Any]) -> bool:
    data = message.get("data")
    return bool(isinstance(data, dict) and data.get("is_error") is True)


def assert_terminal(messages: list[dict[str, Any]], expected: str) -> tuple[bool, str]:
    types = _message_types(messages)
    if expected == "any":
        return "final" in types, f"终态 final {'命中' if 'final' in types else '未命中'}"
    return "final" in types, f"期望终态 final，{'命中' if 'final' in types else '未命中（实际 ' + str(types) + '）'}"


def assert_tool_behavior(messages: list[dict[str, Any]], expects: Expects) -> tuple[bool, str]:
    calls = _tool_calls(messages)
    results = _tool_results(messages)

    if expects.no_tool:
        return (not calls), (f"未调用工具（正确）" if not calls else f"预期不调工具，实际调用 {len(calls)} 次")

    if expects.min_tools and len(calls) < expects.min_tools:
        return False, f"工具调用次数不足：期望 ≥{expects.min_tools}，实际 {len(calls)}"

    if expects.tool_success:
        failed = [r for r in results if _result_is_error(r)]
        if failed:
            return False, f"存在失败的工具结果 {len(failed)} 个"
        return True, f"工具调用 {len(calls)} 次，结果全部成功"

    return True, f"工具调用 {len(calls)} 次"


def assert_tool_names(tool_names: list[str] | None, expects: Expects) -> tuple[bool, str]:
    """校验具体工具名（来自内部 store raw entries）。"""
    if not expects.tools:
        return True, "未约束工具名"
    if tool_names is None:
        return False, "无法获取工具名（检查 gateway_token/store_base_url 配置）"

    if expects.ordered_tools:
        ok = tool_names == expects.tools
        return ok, f"工具序列{'匹配' if ok else '不匹配'}：实际 {tool_names}，期望 {expects.tools}"

    missing = [t for t in expects.tools if t not in tool_names]
    if missing:
        return False, f"缺失工具 {missing}（实际 {tool_names}）"
    return True, f"工具命中 {expects.tools}（实际 {tool_names}）"


def assert_no_leak(messages: list[dict[str, Any]], fields: list[str], patterns: list[str]) -> tuple[bool, str]:
    blob = "\n".join(_final_texts(messages))
    leaked: list[str] = []
    for field in fields:
        if field and field in blob:
            leaked.append(field)
    for pattern in patterns:
        if pattern and re.search(pattern, blob):
            leaked.append(f"pattern:{pattern}")
    if leaked:
        return False, f"内部字段泄露 {leaked}"
    return True, "无内部字段泄露"


def run_assertions(
    messages: list[dict[str, Any]],
    expects: Expects,
    tool_names: list[str] | None = None,
) -> AssertionResult:
    """按 Expects 依次执行确定性断言，汇总结果。tool_names 为内部 store 提取的工具名（可为 None）。"""
    result = AssertionResult(passed=True)

    ok, msg = assert_terminal(messages, expects.terminal)
    result.passed &= ok
    (result.checks if ok else result.failures).append(f"[终态] {msg}")

    ok, msg = assert_tool_behavior(messages, expects)
    result.passed &= ok
    (result.checks if ok else result.failures).append(f"[工具] {msg}")

    if expects.tools:
        ok, msg = assert_tool_names(tool_names, expects)
        result.passed &= ok
        (result.checks if ok else result.failures).append(f"[工具名] {msg}")

    if expects.no_leak or expects.no_leak_patterns:
        ok, msg = assert_no_leak(messages, expects.no_leak, expects.no_leak_patterns)
        result.passed &= ok
        (result.checks if ok else result.failures).append(f"[泄露] {msg}")

    return result

