        String forwardedQuery = appendSourceFiles(query, files, principal);
        if (acceptsEventStream(request)) {
            return proxyService.proxyCreateConversationMultipartStream(forwardedQuery, images, files, idempotencyKey, principal);
        }
        return proxyService.proxyCreateConversationMultipartAsStream(forwardedQuery, images, files, idempotencyKey, principal);
    }

