        }
        return proxyService.proxyChatAsStream(conversationId, body, principal);
    }

    @ApiOperation("Chat with AI conversation and images")
    @PostMapping(value = "/conversations/{conversationId}/chat", consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
    public ResponseEntity<StreamingResponseBody> chatConversationWithImages(
        @PathVariable("conversationId") String conversationId,
        @RequestParam(value = "query", required = false) String query,
        @RequestParam(value = "images", required = false) List<MultipartFile> images,
        @RequestParam(value = "files", required = false) List<MultipartFile> files,
        HttpServletRequest request
    ) {
        AiBizPrincipal principal = resolvePrincipal(request);
        // 续聊上传的 PDF 与新会话保持同一登记口径，避免模型拿到无法回填的临时路径。
        String forwardedQuery = appendSourceFiles(query, files, principal);
        if (acceptsEventStream(request)) {
            return proxyService.proxyChatMultipartStream(conversationId, forwardedQuery, images, files, principal);
        }
        return proxyService.proxyChatMultipartAsStream(conversationId, forwardedQuery, images, files, principal);
    }

    @ApiOperation("Transcribe a recorded audio clip to editable text")
    @PostMapping(value = "/asr/transcriptions", consumes = MediaType.MULTIPART_FORM_DATA_VALUE, produces = MediaType.APPLICATION_JSON_VALUE)
    public ResponseEntity<Map<String, String>> transcribeAudio(
        @RequestParam(value = "audio", required = false) MultipartFile audio,
        HttpServletRequest request
    ) {
        AiBizPrincipal principal = resolvePrincipal(request);
        try {
            // 此接口是输入法能力而不是 Pi 对话入口：只返回文字，绝不创建会话或自动发送给 Agent。
            String text = aliyunAsrService.transcribe(audio, principal.getTraceId());
            return ResponseEntity.ok(Collections.singletonMap("text", text));
        } catch (AliyunAsrService.AsrTranscriptionException exception) {
            return ResponseEntity.status(exception.getStatus())
                .body(Collections.singletonMap("detail", exception.getUserMessage()));
        }
    }

