        return proxyService.proxyMessages(conversationId, queryString, principal);
    }

    @ApiOperation("Interrupt AI conversation")
    @PostMapping(value = "/conversations/{conversationId}/interrupt")
    public ResponseEntity<String> interruptConversation(
