    @Test
    public void buildSignedBizContext_shouldIncludeConversationContextOnlyWhenRequested() throws Exception {
        AiProperties aiProperties = new AiProperties();
        aiProperties.getGateway().setContextSignSecret("unit-test-secret");
        aiProperties.getGateway().setContextTtlSeconds(300L);
        ObjectMapper objectMapper = new ObjectMapper();
        AiContextResolveService contextResolveService = Mockito.mock(AiContextResolveService.class);
        AiGatewayProxyService service = new AiGatewayProxyService(
            aiProperties,
            objectMapper,
            contextResolveService
        );
        AiBizPrincipal principal = new AiBizPrincipal(
            "200",
            "100",
            "trace-1",
            AiUserType.ADMIN,
            List.of(new AiBizVisibleFurnace("1 号炉"))
        );
        Mockito.when(contextResolveService.resolveConversationContext(principal)).thenReturn(
            new AiConversationContext(
                "200",
                "100",
                "一号工厂",
                List.of(new AiConversationContextFurnace("1号炉"))
            )
        );

        String signed = ReflectionTestUtils.invokeMethod(service, "buildSignedBizContext", principal, true);
        Assertions.assertNotNull(signed);

        String[] parts = signed.split("\\.");
        Assertions.assertEquals(3, parts.length);
        String payloadJson = new String(Base64.getUrlDecoder().decode(parts[1]), StandardCharsets.UTF_8);
        JsonNode payload = objectMapper.readTree(payloadJson);

        Assertions.assertEquals("200", payload.path("userId").asText());
        Assertions.assertEquals("100", payload.path("tenantDeptId").asText());
        Assertions.assertEquals("trace-1", payload.path("traceId").asText());
        Assertions.assertEquals("admin", payload.path("userType").asText());
        Assertions.assertFalse(payload.has("visibleFurnaces"));
        Assertions.assertEquals("200", payload.path("conversationContext").path("userId").asText());
        Assertions.assertEquals("100", payload.path("conversationContext").path("tenantDeptId").asText());
        Assertions.assertEquals("一号工厂", payload.path("conversationContext").path("deptName").asText());
        Assertions.assertEquals("1号炉", payload.path("conversationContext").path("furnaces").get(0).path("fnCode").asText());
    }

    @Test
    public void proxyChatMultipart_shouldForwardQueryImagesFilesAndTrustedHeaders() throws Exception {
        AtomicReference<String> contentType = new AtomicReference<>();
        AtomicReference<String> gatewayToken = new AtomicReference<>();
        AtomicReference<String> bizContext = new AtomicReference<>();
        AtomicReference<byte[]> requestBody = new AtomicReference<>();
        HttpServer upstream = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
        upstream.createContext("/ai/conversations/conversation-1/chat", exchange -> {
            contentType.set(exchange.getRequestHeaders().getFirst("Content-Type"));
            gatewayToken.set(exchange.getRequestHeaders().getFirst("X-AI-GW-TOKEN"));
            bizContext.set(exchange.getRequestHeaders().getFirst("X-AI-BIZ-CONTEXT"));
            requestBody.set(exchange.getRequestBody().readAllBytes());
            byte[] response = "{\"accepted\":true}".getBytes(StandardCharsets.UTF_8);
            exchange.getResponseHeaders().set("Content-Type", "application/json");
            exchange.sendResponseHeaders(200, response.length);
            exchange.getResponseBody().write(response);
            exchange.close();
        });
        upstream.start();

        try {
            AiProperties aiProperties = new AiProperties();
            aiProperties.getGateway().setPythonBaseUrl("http://127.0.0.1:" + upstream.getAddress().getPort());
            aiProperties.getGateway().setInternalToken("gateway-token");
            aiProperties.getGateway().setContextSignSecret("unit-test-secret");
            AiGatewayProxyService service = new AiGatewayProxyService(
                aiProperties,
                new ObjectMapper(),
                Mockito.mock(AiContextResolveService.class)
            );
            AiBizPrincipal principal = new AiBizPrincipal(
                "200",
                "100",
                "trace-1",
                AiUserType.ADMIN,
                List.of()
            );
            byte[] imageBytes = "image-binary".getBytes(StandardCharsets.UTF_8);
            MockMultipartFile image = new MockMultipartFile("images", "one.png", "image/png", imageBytes);
            byte[] pdfBytes = "%PDF-test".getBytes(StandardCharsets.UTF_8);
            MockMultipartFile pdf = new MockMultipartFile("files", "order.pdf", "application/pdf", pdfBytes);

            ResponseEntity<StreamingResponseBody> response = service.proxyChatMultipartAsStream(
                "conversation-1",
                "分析图片",
                List.of(image),
                List.of(pdf),
                principal
            );
            ByteArrayOutputStream downstream = new ByteArrayOutputStream();
            Assertions.assertNotNull(response.getBody());
            response.getBody().writeTo(downstream);

            Assertions.assertEquals(200, response.getStatusCodeValue());
            Assertions.assertEquals("{\"accepted\":true}", downstream.toString(StandardCharsets.UTF_8.name()));
            Assertions.assertTrue(contentType.get().startsWith("multipart/form-data; boundary="));
            Assertions.assertEquals("gateway-token", gatewayToken.get());
            Assertions.assertTrue(bizContext.get().startsWith("v1."));
            String multipartBody = new String(requestBody.get(), StandardCharsets.UTF_8);
            Assertions.assertTrue(multipartBody.contains("name=\"query\""));
            Assertions.assertTrue(multipartBody.contains("分析图片"));
            Assertions.assertTrue(multipartBody.contains("name=\"images\""));
            Assertions.assertTrue(multipartBody.contains("image-binary"));
            Assertions.assertTrue(multipartBody.contains("name=\"files\""));
            Assertions.assertTrue(multipartBody.contains("document-1.pdf"));
            Assertions.assertTrue(multipartBody.contains("%PDF-test"));
        } finally {
            upstream.stop(0);
        }
    }
